///////// 2. 초기화 영역 /////////

// 조건 평가 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_conds
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_conds = async function () {
    const binds = [{ id: "btn_FileDown", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "btn_deleteAttachFile", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_2", fn: function(){ return ((String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "if_attachFileNm_3", fn: function(){ return (!(String(((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })())) == null ? '' : ((dlt_bbsList.getCellData(0, "attachFileNm") ?? (() => { throw new Error("unresolved:" + "entity.attachFileNm"); })()))).length === 0)); } }, { id: "c_when_40", fn: function(){ return (!(String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList")))).length === 0)); } }, { id: "c_when_97", fn: function(){ return ((String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "bbsList" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("bbsList")))).length === 0) && (String((((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.modifyYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modifyYn"))) == null ? '' : (((cv) => (cv !== undefined && cv !== null && cv !== "") ? cv : (console.warn("[sdd] 컨텍스트 키 미충전 — " + "param.modifyYn" + " (as-is EL 부재 = 빈값이라 진행합니다)"), ""))(dma_pageContext.get("modifyYn")))).length === 0)); } }];
    let applied = 0;
    for (let i = 0; i < binds.length; i++) {
        const b = binds[i];
        try {
            const ok = !!b.fn();
            const comp = $c.util.getComponent(b.id);
            if (comp && comp.setStyle) { comp.setStyle("display", ok ? "" : "none"); }
            else if (comp) { if (ok) { if (comp.show) { comp.show(); } } else if (comp.hide) { comp.hide(); } }
            if (ok && b.grids) {
                for (let gi = 0; gi < b.grids.length; gi++) {
                    const gc = $c.util.getComponent(b.grids[gi]);
                    if (gc && gc.refreshGridView) { gc.refreshGridView(); }
                }
            }
            applied++;
        } catch (e) { await $c.exception.handleError(e, { notify: "none", context: "conds:" + b.id }); }
    }
    return applied;
};

/**
 * @method
 * @name scwin.init_pageBody
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_pageBody = function () {
    try {
        /* sdd-asis-lifecycle:begin onpageload — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
        $c.util.getComponent('dlt_bbsList').setCellData(0, 'wrtrNm', $c.session.getUserInfo("empNm"));
        $c.util.getComponent('dlt_bbsList').setCellData(0, 'wrtrEmail', js_email);
        /* sdd-asis-lifecycle:end */

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf07421.onpageload' }); }
};

// [A] 초기 목록 미해결 — 자기 목록을 채우는 tx 가 2개다(tx_changePage, tx_fn_register) — 어느 것이 «열자마자» 인지 정할 근거가 없다


// 화면 전환 파라미터 수신 — 엔진 표준(§106). 진입 파라미터 전체를 컨텍스트 dataMap 에 담는다. onpageload 합성 단계.
/**
 * @method
 * @name scwin.init_recvParam
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

scwin.upd_attachBinFiles = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles"]');

scwin.upd_attachBinFiles2 = (typeof __krxFileControl === 'function') ? __krxFileControl('upd_attachBinFiles2') : ((typeof $c !== 'undefined' && $c.win && $c.win.getFrame && $c.win.getFrame() && $c.win.getFrame().render) ? $c.win.getFrame().render : document).querySelector('[id="upd_attachBinFiles2"]');

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        await scwin.init_conds();
        scwin.init_pageBody();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf07421.onpageload' });
    }
};


