/**
 * @method
 * @name scwin.changePage
 * @author Inswave
 * @date 2026. 09. 29
 * @param ver1 ver2
 * @returns
 * @hidden N
*/
scwin.changePage = async function (ver1, ver2) {
    /* sdd-asis-lifecycle:begin changePage — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const form = (document.moveForm || { elements: [] });
    if ('1' === ver1) {
        $c.util.getComponent('dma_changePageReq').set('nowPage', ver2);
    } else {
        if ('2' === ver1) {
            $c.util.getComponent('dma_changePageReq').set('nowPage', '20');
            $c.util.getComponent("dma_changePageReq").set("method", 'loadDetail');
        } else {
            if ('3' === ver1) {
                $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
                form.action = '/konex/bbs.do';
                $c.util.getComponent("dma_changePageReq").set("method", 'searchCommentLetterList');
            } else {
                if ('4' === ver1) {
                    $c.util.getComponent('dma_changePageReq').set('nowPage', '40');
                }
            }
        }
    }
    await scwin.tx_changePage();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.goList
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.goList = async function () {
    /* sdd-asis-lifecycle:begin fn_goList — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    const frm = (document.CommentLetterListForm || { elements: [] });
    frm.action = '/konex/bbs.do';
    $c.util.getComponent("dma_changePageReq").set("method", 'searchCommentLetterList');
    $c.util.getComponent('dma_changePageReq').set('nowPage', '30');
    { const nr = await scwin.tx_fn_goList(); if (nr && nr.responseJSON && nr.responseJSON.success === true) { $c.win.moveUrl("/jldfil51300/jldfil51300.xml", { "method": 'searchCommentLetterList', "nowPage": '30' }); } };
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.register
 * @author Inswave
 * @date 2026. 09. 29
 * @param
 * @returns
 * @hidden N
*/
scwin.register = async function () {
    /* sdd-asis-lifecycle:begin fn_register — as-is 원문 본문(전환 이관 · 포팅 적용됨) */
    if (await scwin.nullChk($c.util.getComponent("ipt_wrtrNm"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_regTelNo"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_wrtrEmail"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("ipt_contnTitle"))) {
        return;
    }
    if (await scwin.nullChk($c.util.getComponent("txa_contnContn"))) {
        return;
    }
    const frm = (document.CommentLetterListForm || { elements: [] });
    frm.action = '/konex/bbs.do';
    $c.util.getComponent("dma_changePageReq").set("method", 'registCommentLetter');
    $c.util.getComponent('dma_changePageReq').set('modifyYn', '' + dma_pageContext.get("modifyYn") + '');
    $c.util.getComponent('dma_changePageReq').set('replyYn', '' + dma_pageContext.get("replyYn") + '');
    $c.util.getComponent('dma_changePageReq').set('contnId', '' + dma_pageContext.get("contnId") + '');
    $c.util.getComponent('dma_changePageReq').set('contnAttachSeq', '' + dma_pageContext.get("contnAttachSeq") + '');
    await scwin.tx_fn_register();
    /* sdd-asis-lifecycle:end */
};


/**
 * @method
 * @name scwin.isNull
 * @author Inswave
 * @date 2026. 09. 29
 * @param _obj _msg
 * @returns
